using EXT = Microsoft.Dynamics.Integration.Telemetry;
public class METSysGlobalTelemetry
{
}

Method.Source:
    [PreHandlerFor(classStr(Global), staticMethodStr(Global, error))]
    public static void Global_Pre_error(XppPrePostArgs args)
    {
        str eventName;
        str exceptionMessage = Args.getArg('txt');

        eventName   = "@MET:EvntBtchErr";
        if (BatchHeader::isExecutingInBatch())
        {
            Batch   batch = BatchHeader::getCurrentBatchTask();
            Map customProperties = new Map(Types::String, Types::String);
            customProperties.insert("@MET:BtchJId", strFmt('%1',batch.BatchJobId));
            customProperties.insert("@MET:BtchTsk", strFmt('%1',batch.RecId));
            customProperties.insert("@MET:BtchNme", batch.Caption);
            customProperties.insert("@MET:SrtrDTme", strFmt('%1',batch.StartDateTime));
            customProperties.insert("@MET:LglEntty", batch.Company);
            customProperties.insert("@MET:ExptnMssg", exceptionMessage);
            customProperties.insert('CallStack', METSysGlobalTelemetry::formatXppCallStack(xSession::xppCallStack()));
            // Log custom event
            SysGlobalTelemetry::logEventWithCustomProperties(eventName, customProperties);

        }
    }

    /// <summary>
    /// DMF Error Telemetry
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [DataEventHandler(tableStr(DMFDefinitionGroupExecution), DataEventType::Updated)]
    public static void DMFDefinitionGroupExecution_onUpdated(Common sender, DataEventArgs e)
    {
        DMFDefinitionGroupExecution dMFDefinitionGroupExecution = sender;
        str eventName, DMFerror;
        boolean isError = false;
        
        eventName           = "@MET:EvntNme";
        if (dMFDefinitionGroupExecution.StagingStatus == DMFBatchJobStatus::Error)
        {
            DMFerror = "@MET:DErr";
            isError = true;
        }
        else if (dMFDefinitionGroupExecution.TargetStatus == DMFBatchJobStatus::Error)
        {
            str errorMessage = "@DMF:StagingToTargetImportFailed";
            DMFerror = "@MET:METError" + ' ' + strFmt("@DMF:EntityImportError", dMFDefinitionGroupExecution.Entity, errorMessage);
            isError = true;
        }

        if (isError)
        {
            Map customProperties = new Map(Types::String, Types::String);
            customProperties.insert("@MET:DMExctnGrp", dMFDefinitionGroupExecution.DefinitionGroup);
            customProperties.insert("@MET:DeftnEntNme", dMFDefinitionGroupExecution.Entity);
            customProperties.insert("@MET:ExcptnMssg", DMFerror);
            customProperties.insert("@MET:ExctnLglEntty", dMFDefinitionGroupExecution.Company);
            customProperties.insert("@MET:ExuctnId", dMFDefinitionGroupExecution.ExecutionId);
            customProperties.insert("@MET:StagngErrCnt", int2Str(dMFDefinitionGroupExecution.StagingErrorCount));
            customProperties.insert("@MET:Stngnstus", enum2Str(dMFDefinitionGroupExecution.StagingStatus));
            customProperties.insert("@MET:DTrgtErrCnt", int2Str(dMFDefinitionGroupExecution.TargetErrorCount));
            customProperties.insert("@MET:TrgtStus", enum2Str(dMFDefinitionGroupExecution.TargetStatus));
            customProperties.insert('CallStack', METSysGlobalTelemetry::formatXppCallStack(xSession::xppCallStack()));
            // CS CB718 VM 28032024-DMFLoggingAppinsights
            DMFerror += METSysGlobalTelemetry::getPrimaryKeyDetails(dMFDefinitionGroupExecution);
            customProperties.insert("@MET:ExcptnMssg", DMFerror);
            // CE
            // Log custom event
            SysGlobalTelemetry::logEventWithCustomProperties(eventName, customProperties);
        }
    }

    public static str formatXppCallStack(container _xppCallStack)
    {
        str result = '';

        // Each stack frame is four elements [Method, Line Number, Model Publisher, Model]
        for (int i = 1; i <= conLen(_xppCallStack); i += 4)
        {
            str methodName = conPeek(_xppCallStack, i);
            str lineNum = conPeek(_xppCallStack, i + 1);
            str publisher = conPeek(_xppCallStack, i + 2);
            str model = conPeek(_xppCallStack, i + 3);

            // Add a newline between stack frames
            if (i > 1)
            {
                result += '\n at';
            }
            
            // Model identifer
            if (publisher || model)
            {
                result += strFmt('[%1%2%3]', publisher, (publisher && model ? ':' : ''), model);
            }
            
            // Code
            result += strFmt('%1%2', methodName, (lineNum && lineNum != '0' ? ':' + lineNum : ''));
        }

        return result;
    }

    /// <summary>
    /// CB718 VM 28032024-DMFLoggingAppinsights
    /// Find the primary key and update the error message
    /// </summary>
    /// <param name = "_dmfDefinitionGroupExecution">_dmfDefinitionGroupExecution</param>
    /// <returns>DMFErrorMessage</returns>
    public static DMFErrorMessage getPrimaryKeyDetails(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
    {
        SysDictIndex keyIndex;
        DMFStagingValidationLog DMFStagingValidationLog;
        DictField dictField;
        int fieldIndex;
        SysDictTable sysDictTable;
        Common buffer;
        SysDictTable dictTable;
        DMFErrorMessage dmfError;

        while select * from DMFStagingValidationLog
                where DMFStagingValidationLog.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId
        {
            TableName tablename = DMFStagingValidationLog.StagingTableName;

            sysDictTable = new SysDictTable(tablename2id(tablename));
            if (sysDictTable)
            {
                TableId tableId = sysDictTable.id();
                str fieldid;
                keyIndex = new SysDictIndex(tableId, sysDictTable.primaryIndex());
                if (keyIndex)
                {
                    for (fieldIndex = 1; fieldIndex <= keyIndex.numberOfFields(); fieldIndex++)
                    {
                        dictField = new DictField(tableId, keyindex.field(fieldindex));
                        dictTable = new SysDictTable(tableId);
                        buffer = dictTable.makeRecord();
                        fieldid = fieldId2Name(tableId, dictfield.id());

                        select firstonly buffer 
                            where buffer.RecId == DMFStagingValidationLog.StagingRecId;

                        if (fieldid != 'DefinitionGroup' && fieldid != 'ExecutionId')
                        {
                            dmfError += strFmt("@MET:StFildId",fieldId2Name(tableId, dictfield.id()),buffer.(dictfield.id()),DMFStagingValidationLog.ErrorMessage);
                        }
                    }
                }
            }
        }
        return dmfError;
    }
